// SPDX-License-Identifier: CC0-1.0
#include TRIE_SOURCE
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <random>
#include <string>
#include <vector>
using Clock=std::chrono::steady_clock;
using Time=Clock::time_point;
static double ms(Time a,Time b) {return std::chrono::duration<double,std::milli>(b-a).count();}
template<int L> int run(std::size_t n,int kind,int reps) {
 using U=std::uint64_t;constexpr U mask=std::numeric_limits<U>::max()>>(63-L);
 std::mt19937_64 rng(0x51131415);std::vector<U> keys(n),queries(std::min(n*4,std::size_t{32768}));
 for(std::size_t i=0;i<n;++i){U k=rng()&mask;if(kind==1)k&=65535;if(kind==2)k=static_cast<U>(i%16);keys[i]=k;}
 for(std::size_t i=0;i<queries.size();++i)queries[i]=(i%2 ? rng()&mask : keys[i%keys.size()]);
 double add=0,unique=0,count=0,xorq=0,extreme=0,kth=0,less=0,lazy=0,del=0;U sum=0;
 for(int r=0;r<reps;++r) {
  auto t0=Clock::now();BinaryTrie<U,L> tr;for(auto x:keys)tr.add(x);auto t1=Clock::now();
  for(auto x:keys)sum+=tr.insert_unique(x);auto t2=Clock::now();
  for(auto x:queries)sum+=tr.count(x);auto t3=Clock::now();
  for(auto x:queries)sum+=tr.min_xor(x).first;auto t4=Clock::now();
  for(std::size_t i=0;i<queries.size();++i){tr.operate_xor(queries[i]);sum+=(i%2 ? tr.max_element().first : tr.min_element().first);}auto t5=Clock::now();
  for(auto x:queries)sum+=tr.get_kth(static_cast<std::int64_t>(x%n+1)).first;auto t6=Clock::now();
  for(auto x:queries)sum+=tr.count_less(x);auto t7=Clock::now();
  for(auto x:queries)tr.operate_xor(x);auto t8=Clock::now();
  for(auto x:keys)sum+=tr.del(x);auto t9=Clock::now();
  add+=ms(t0,t1);unique+=ms(t1,t2);count+=ms(t2,t3);xorq+=ms(t3,t4);extreme+=ms(t4,t5);kth+=ms(t5,t6);less+=ms(t6,t7);lazy+=ms(t7,t8);del+=ms(t8,t9);
 }
 std::cout<<"{\"bits\":"<<L+1<<",\"n\":"<<n<<",\"kind\":"<<kind<<",\"add\":"<<add<<",\"unique\":"<<unique<<",\"count\":"<<count<<",\"xor\":"<<xorq<<",\"extreme\":"<<extreme<<",\"kth\":"<<kth<<",\"less\":"<<less<<",\"lazy\":"<<lazy<<",\"del\":"<<del<<",\"sum\":"<<sum<<"}\n";
 return 0;
}
int main(int argc,char**argv) {if(argc!=5)return 2;int bits=std::atoi(argv[1]);auto n=static_cast<std::size_t>(std::strtoull(argv[2],nullptr,10));int kind=std::atoi(argv[3]),reps=std::atoi(argv[4]);if(bits==30)return run<29>(n,kind,reps);if(bits==31)return run<30>(n,kind,reps);return run<63>(n,kind,reps);}

