from pathlib import Path
import subprocess,json,statistics,random,fcntl
p=Path(__file__).parent;rows=[];builds=[];rng=random.Random(731381)
configs={'gcc_native':['/usr/bin/g++','-march=native'],'clang_default':['/usr/bin/clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']}
variants=['baseline','stride_v1'];ops=['add','unique','count','xor','extreme','kth','less','lazy','del']
for c,cc in configs.items():
 for v in variants:
  exe=p/f'api_{c}_{v}';cmd=['taskset','-c','6',*cc,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',f'-DTRIE_SOURCE="{p/(v+".hpp")}"',str(p/'api_bench.cpp'),'-o',str(exe)];q=subprocess.run(cmd,capture_output=True,text=True);assert q.returncode==0,q.stderr;builds.append(dict(config=c,variant=v,cmd=cmd,diagnostics=q.stderr))
with open('/tmp/sirkit_performance_cpu14.lock','a')as lock:
 fcntl.flock(lock,fcntl.LOCK_EX)
 for c in configs:
  for bits,n,kind in [(30,32,0),(64,32,0),(30,100000,0),(31,100000,0),(64,100000,0),(64,100000,1),(64,100000,2)]:
   raw={v:[]for v in ['baseline','control','stride_v1']};checks={}
   for rep in range(7):
    vs=list(raw);rng.shuffle(vs)
    for v in vs:
     exe=p/f'api_{c}_{"baseline"if v=="control"else v}';q=subprocess.run(['taskset','-c','14',str(exe),str(bits),str(n),str(kind),'30'if n==32 else'1'],capture_output=True,text=True);assert q.returncode==0 and not q.stderr;d=json.loads(q.stdout);raw[v].append(d);checks[v]=d['sum']
    assert len(set(checks.values()))==1,(c,bits,n,kind,checks)
   med={v:{op:statistics.median(x[op]for x in xs)for op in ops}for v,xs in raw.items()};rec=dict(config=c,bits=bits,n=n,kind=kind,raw=raw,median_ms=med,ratio={v:{op:med[v][op]/med['baseline'][op]for op in ops}for v in raw});rows.append(rec);(p/'api-results.json').write_text(json.dumps(dict(builds=builds,rows=rows),indent=2));print(c,bits,n,kind,rec['ratio']['stride_v1'],flush=True)

