from pathlib import Path
base=Path('/tmp/sirkit_binary_stride_20261026/baseline.hpp').read_text()
s=base[:base.index('#if defined(__GNUC__)')]
s=s.replace('kBits = MAX_LOG + 1;', 'kBits = MAX_LOG + 1;\n    static constexpr size_type kLevels = (kBits + 1) / 2;')
