// SPDX-License-Identifier: CC0-1.0
// 独立した表現比較。ID操作・削除・NODES制限・例外保証は実装していない。
#include <algorithm>
#include <array>
#include <bit>
#include <chrono>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <memory>
#include <random>
#include <string>
#include <vector>

#define SKIP_RUNTIME_CHECKS
#define BinaryTrie CurrentBinaryTrie
#include "../baseline.hpp"
#undef BinaryTrie

struct Current : CurrentBinaryTrie<std::uint32_t,29> {
    std::uint32_t min_xor(std::uint32_t x) const {return CurrentBinaryTrie::min_xor(x).first;}
    std::size_t bytes() const {return 0;}
    std::size_t allocations() const {return 0;}
    std::size_t live_bytes() const {return 0;}
};

namespace reinsirk::detail {
template<class T> struct Pool {
    static constexpr std::size_t block_size=4096;
    std::vector<std::unique_ptr<T[]>> data;
    std::size_t next=0;
    T *acquire() {
        if(next%block_size==0) data.push_back(std::make_unique<T[]>(block_size));
        auto *p=&data[next/block_size][next%block_size];
        ++next;
        return p;
    }
    std::size_t bytes() const {return data.size()*sizeof(T)*block_size;}
};
struct Node { Node *child[2]{}; std::size_t count=0; };
struct Leaf { std::size_t count=0; void *id_slot=nullptr; }; // ID枠への非所有参照。prototypeでは未使用。
constexpr auto make_permutations() {
    std::array<std::array<unsigned char,16>,4> result{};
    for(unsigned x=0;x<4;++x) for(unsigned m=0;m<16;++m)
        for(unsigned i=0;i<4;++i) if((m>>i)&1) result[x][m]|=static_cast<unsigned char>(1u<<(i^x));
    return result;
}
inline constexpr auto permutations=make_permutations();
}

// Mask=falseは件数順に確認、Mask=trueは4bit占有マスクを使う。
template<int K,bool Mask=false> struct Prototype {
    using Node=reinsirk::detail::Node;
    using Leaf=reinsirk::detail::Leaf;
    static constexpr unsigned width=1u<<K;
    struct Bucket { std::array<Leaf,width> leaf{}; std::size_t meta=0; };
    reinsirk::detail::Pool<Node> nodes;
    reinsirk::detail::Pool<Bucket> buckets;
    Node *root=nodes.acquire();
    static constexpr int Bits=30;
    void add(std::uint32_t x) {
        auto *p=root;
        ++p->count;
        for(int i=Bits-1;i>K-1;--i) {
            auto &c=p->child[(x>>i)&1u];
            if(!c) {
                if(i==K) c=reinterpret_cast<Node*>(buckets.acquire());
                else c=nodes.acquire();
            }
            if(i==K) {
                auto &b=*reinterpret_cast<Bucket*>(c);
                ++b.leaf[x&(width-1)].count;
                if constexpr(Mask) b.meta|=std::size_t{1}<<(x&(width-1));
                else ++b.meta;
            } else {
                p=c;
                ++p->count;
            }
        }
    }
    std::uint32_t min_xor(std::uint32_t x) const {
        auto *p=root;
        std::uint32_t answer=0;
        for(int i=Bits-1;i>K-1;--i) {
            const auto z=(x>>i)&1u;
            const auto c=p->child[z]?z:(z^1u);
            answer|=(c^z)<<i;
            if(i==K) {
                const auto &b=*reinterpret_cast<const Bucket*>(p->child[c]);
                if constexpr(Mask) {
                    static_assert(K==2);
                    const auto transformed=reinsirk::detail::permutations[x&3][b.meta];
                    return answer|std::countr_zero(static_cast<unsigned>(transformed));
                } else {
                    for(unsigned v=0;v<width;++v) if(b.leaf[(x^v)&(width-1)].count) return answer|v;
                }
            }
            p=p->child[c];
        }
        return answer;
    }
    std::size_t count(std::uint32_t x) const {
        auto *p=root;
        for(int i=Bits-1;i>K-1;--i) {
            p=p->child[(x>>i)&1u];
            if(!p) return 0;
        }
        return reinterpret_cast<const Bucket*>(p)->leaf[x&(width-1)].count;
    }
    auto bytes() const {return nodes.bytes()+buckets.bytes();}
    auto allocations() const {return nodes.data.size()+buckets.data.size();}
    auto live_bytes() const {return nodes.next*sizeof(Node)+buckets.next*sizeof(Bucket);}
};
struct Binary {
    using Node=reinsirk::detail::Node;
    reinsirk::detail::Pool<Node> nodes;
    Node *root=nodes.acquire();
    void add(std::uint32_t x) {
        auto *p=root;
        ++p->count;
        for(int i=29;i>=0;--i) {
            auto &c=p->child[(x>>i)&1u];
            if(!c)c=nodes.acquire();
            p=c;
            ++p->count;
        }
    }
    std::uint32_t min_xor(std::uint32_t x) const {
        auto *p=root;
        std::uint32_t answer=0;
        for(int i=29;i>=0;--i) {
            const auto z=(x>>i)&1u;
            const auto c=p->child[z]?z:(z^1u);
            answer|=(c^z)<<i;
            p=p->child[c];
        }
        return answer;
    }
    std::size_t count(std::uint32_t x) const {
        auto *p=root;
        for(int i=29;i>=0&&p;--i) p=p->child[(x>>i)&1u];
        return p?p->count:0;
    }
    auto bytes() const {return nodes.bytes();}
    auto allocations() const {return nodes.data.size();}
    auto live_bytes() const {return nodes.next*sizeof(Node);}
};

template<class Trie> void run(const char *kind,const char *name,const std::vector<std::uint32_t> &keys,const std::vector<std::uint32_t> &queries) {
    const auto now=[] {return std::chrono::steady_clock::now();};
    const auto elapsed=[](auto a,auto b) {return std::chrono::duration<double,std::milli>(b-a).count();};
    auto begin=now();
    Trie trie;
    for(auto x:keys)trie.add(x);
    auto added=now();
    std::uint64_t checksum=0;
    for(auto x:queries)checksum+=trie.min_xor(x);
    auto queried=now();
    for(auto x:keys)checksum+=trie.count(x);
    auto found=now();
    std::cout<<kind<<','<<name<<','<<elapsed(begin,added)<<','<<elapsed(added,queried)<<','<<elapsed(queried,found)<<','<<trie.bytes()<<','<<trie.live_bytes()<<','<<trie.allocations()<<','<<checksum<<'\n';
}
int main(int argc,char **argv) {
    const unsigned seed=argc>1?std::stoul(argv[1]):1;
    std::mt19937 random(seed);
    std::cout<<"distribution,representation,add_ms,minxor_ms,count_ms,capacity_bytes,live_bytes,allocations,checksum\n";
    for(unsigned bits:{30u,20u,16u}) {
        std::vector<std::uint32_t> keys(200000),queries(1000000);
        for(auto &x:keys)x=random()&((1u<<bits)-1);
        for(auto &x:queries)x=random()&((1u<<bits)-1);
        const char *name=bits==30?"random30":bits==20?"dense20":"dense16";
        if(seed%2) {
            run<Binary>(name,"binary",keys,queries);
            run<Current>(name,"current",keys,queries);
            run<Prototype<2>>(name,"leaf2_counts",keys,queries);
            run<Prototype<2,true>>(name,"leaf2_mask",keys,queries);
            run<Prototype<3>>(name,"leaf3_counts",keys,queries);
            run<Prototype<4>>(name,"leaf4_counts",keys,queries);
        } else {
            run<Prototype<4>>(name,"leaf4_counts",keys,queries);
            run<Prototype<3>>(name,"leaf3_counts",keys,queries);
            run<Prototype<2,true>>(name,"leaf2_mask",keys,queries);
            run<Prototype<2>>(name,"leaf2_counts",keys,queries);
            run<Binary>(name,"binary",keys,queries);
            run<Current>(name,"current",keys,queries);
        }
    }
    return 0;
}

