// SPDX-License-Identifier: CC0-1.0
#define main micro_benchmark_main
#include "micro.cpp"
#undef main
#include <cassert>
#include <limits>

template<class T> void check(std::uint32_t seed) {
    T trie;
    std::mt19937 random(seed);
    std::vector<std::uint32_t> reference;
    for(int i=0;i<200;++i) {
        const auto x=i%2?random()&1023u:random()&((1u<<30)-1);
        trie.add(x);
        reference.push_back(x);
        for(int j=0;j<20;++j) {
            const std::uint32_t query=j%2?random()&1023u:random()&((1u<<30)-1);
            std::uint32_t expected=std::numeric_limits<std::uint32_t>::max();
            for(auto value:reference)expected=std::min(expected,value^query);
            assert(trie.min_xor(query)==expected);
            assert(trie.count(query)==static_cast<std::size_t>(std::count(reference.begin(),reference.end(),query)));
        }
        assert(trie.count(x)==static_cast<std::size_t>(std::count(reference.begin(),reference.end(),x)));
    }
    for(auto x:{0u,1u,2u,3u,(1u<<30)-1}) {
        trie.add(x);
        trie.add(x);
        assert(trie.min_xor(x)==0);
    }
}
int main() {
    for(auto seed:{1u,2u,3u,19u,31u}) {
        check<Binary>(seed);
        check<Current>(seed);
        check<Prototype<2>>(seed);
        check<Prototype<2,true>>(seed);
        check<Prototype<3>>(seed);
        check<Prototype<4>>(seed);
    }
}

